import { NextRequest } from "next/server";
import { pool } from "@/lib/db";
import { json } from "@/lib/http";
import { CONTENT_VISIBLE, NOT_BLOCKED, NO_STORE, talentGate } from "@/lib/talents";
import { MOMENT_COLS, MOMENT_SHOWN, momentJson, type MomentRow } from "@/lib/sijill";

export const dynamic = "force-dynamic";

// Achievement moments (generated by the system, never written by members) with their reactions.
// GET ?scope=friends (default): the people the member follows plus the member's own moments.
// GET ?scope=user&u=<username>: one member's moments. ?before=<id> pages back, ?locale= names certificates.
// A moment shows only while its owner shows that section; blocked members, suspended and hidden profiles are left out;
// private accounts only for their approved followers.
const PAGE = 30;
export async function GET(req: NextRequest) {
  const g = await talentGate(req, "moments", 90);
  if (g.res) return g.res;
  const sp = req.nextUrl.searchParams;
  const before = /^\d{1,18}$/.test(sp.get("before") ?? "") ? sp.get("before") : null;
  const user = sp.get("scope") === "user" ? String(sp.get("u") ?? "").toLowerCase().slice(0, 40) : null;
  const locale = (sp.get("locale") ?? "en").slice(0, 2);
  const who = user !== null
    ? "c.username = $3"
    : "(m.user_id = $1 OR EXISTS (SELECT 1 FROM community_follows f WHERE f.follower_id = $1 AND f.followee_id = m.user_id))";
  const r = await pool()!.query(
    `SELECT ${MOMENT_COLS}
       FROM community_moments m JOIN community_profiles c ON c.user_id = m.user_id
      WHERE ${who} AND ($2::bigint IS NULL OR m.id < $2)
        AND (m.user_id = $1 OR (c.public AND NOT c.suspended AND ${MOMENT_SHOWN} AND ${NOT_BLOCKED("m.user_id")} AND ${CONTENT_VISIBLE("m.user_id")}))
      ORDER BY m.id DESC LIMIT ${PAGE + 1}`,
    user !== null ? [g.me.id, before, user] : [g.me.id, before],
  );
  const rows = r.rows.slice(0, PAGE) as MomentRow[];
  return json({ moments: rows.map((x) => momentJson(x, locale)), more: r.rows.length > PAGE ? String(rows[rows.length - 1].id) : null }, 200, NO_STORE);
}
